import{_ as s,c as i,o,a2 as t}from"./chunks/framework.DkPtUiZm.js";const m=JSON.parse('{"title":"Fiche Google Play — proposition pour SIA UI Demo","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fiche-google-play.md","filePath":"guides/fiche-google-play.md","lastUpdated":1795438092000}'),a={name:"guides/fiche-google-play.md"};function n(l,e,r,c,p,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="fiche-google-play-—-proposition-pour-sia-ui-demo" tabindex="-1">Fiche Google Play — proposition pour SIA UI Demo <a class="header-anchor" href="#fiche-google-play-—-proposition-pour-sia-ui-demo" aria-label="Permalink to &quot;Fiche Google Play — proposition pour SIA UI Demo&quot;">​</a></h1><p>Brouillon à relire par l’éditeur avant publication. Aucune fiche n’a été envoyée. Les coordonnées de contact et l’URL HTTPS de confidentialité doivent être fournies par l’éditeur dans Play Console ; aucun compte ou contact personnel n’est inventé ici.</p><h2 id="nom" tabindex="-1">Nom <a class="header-anchor" href="#nom" aria-label="Permalink to &quot;Nom&quot;">​</a></h2><p>SIA UI Demo</p><h2 id="description-courte" tabindex="-1">Description courte <a class="header-anchor" href="#description-courte" aria-label="Permalink to &quot;Description courte&quot;">​</a></h2><p>Explorez les composants SIA UI, leurs thèmes et leurs animations sur Android.</p><h2 id="description-complete" tabindex="-1">Description complète <a class="header-anchor" href="#description-complete" aria-label="Permalink to &quot;Description complète&quot;">​</a></h2><p>Découvrez SIA UI dans une application interactive conçue pour explorer son système de composants et ses interactions sur mobile.</p><p>Parcourez le catalogue, recherchez un composant et essayez ses variantes : boutons, champs de saisie, formulaires, calendriers, sélecteurs horaires, onglets, étapes, indicateurs de chargement, feuilles et navigation.</p><p>Personnalisez les couleurs, les thèmes clair et sombre, la barre de navigation et les transitions. Essayez les parcours de démonstration : contacts, fiches de détail, création, modification, filtres et actions de sélection.</p><p>L’application s’adresse aux développeurs, designers et personnes qui souhaitent évaluer les possibilités de SIA UI sur Android. Elle permet d’examiner les interfaces et les comportements ; elle ne génère pas le code d’une application.</p><p>La session et les rôles sont simulés localement. Aucun compte externe n’est requis. Utilisez des données fictives : les exemples de contacts et les réglages restent sur l’appareil. Les photos ou documents ne sont sélectionnés qu’à votre initiative, et aucun transfert de fichier vers un serveur du projet n’est effectué.</p><h2 id="notes-pour-l-acces-et-la-revue-google" tabindex="-1">Notes pour l’accès et la revue Google <a class="header-anchor" href="#notes-pour-l-acces-et-la-revue-google" aria-label="Permalink to &quot;Notes pour l’accès et la revue Google&quot;">​</a></h2><ol><li>Au lancement, conserver le nom fictif Alex ou saisir un nom de démonstration.</li><li>Choisir le rôle Administrateur pour accéder à tous les parcours.</li><li>Appuyer sur Ouvrir la démonstration.</li><li>Aucun identifiant distant, mot de passe ni code reçu par SMS n’est nécessaire.</li><li>Composants → Tous permet de rechercher les composants et d’ouvrir les exemples.</li><li>Personnaliser permet de changer le thème, les couleurs et la navigation.</li><li>Les pages d’erreur et de refus accessibles depuis Aide sont des scénarios explicites de démonstration.</li><li>La page Confidentialité est accessible avant connexion et dans Compte.</li></ol><h2 id="visuels-disponibles" tabindex="-1">Visuels disponibles <a class="header-anchor" href="#visuels-disponibles" aria-label="Permalink to &quot;Visuels disponibles&quot;">​</a></h2><ul><li>Icône de fiche 512 × 512 avec l’identité SIA.</li><li>Deux images de présentation 1024 × 500, claire et sombre.</li><li>Douze captures Android 1080 × 1920 : catalogue, formulaire, clavier, BottomSheet, calendrier et Contacts, chacun dans les deux thèmes.</li><li>Huit compositions marketing avec téléphones en volume, textes français et continuité par paires, prêtes à importer dans la section téléphone.</li><li>Une sélection simple alternative de huit captures et les textes alternatifs.</li></ul><p>Le <a href="./visuels-google-play.html">guide des visuels Google Play</a> donne les fichiers, le ZIP, les aperçus, les prompts imagegen des compositions marketing et leur provenance. Les prises de vue de référence viennent de l&#39;APK preview 1.0.0 installé sur un téléphone. Reprendre les images concernées si la version finale de l&#39;application change visuellement avant l&#39;envoi sur Google Play.</p><p>La catégorie « Bibliothèques et démos », si disponible, correspond au catalogue ; choisir la catégorie proposée la plus pertinente dans la Console. Ne pas annoncer une disponibilité iOS ni une parité de toutes les fonctions web sur la fiche Android.</p>',18)])])}const h=s(a,[["render",n]]);export{m as __pageData,h as default};
